function App() {
  const layout = { title: { template: '%s | Acme', default: 'Acme' } };
  const page = { title: 'Blue Sneakers', description: 'Comfy and stylish.', openGraph: {} };
  const resolvedTitle = page.title
    ? layout.title.template.replace('%s', page.title)
    : layout.title.default;
  const ogTitle = page.openGraph.title ?? page.title; // OG falls back to page title
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>&lt;title&gt;: <b>{resolvedTitle}</b></p>
      <p>og:title: <b>{ogTitle}</b></p>
      <p>meta description: {page.description}</p>
    </div>
  );
}

