// Anti-pattern: setting metadata on the client in a 'use client' page
function App() {
  // Pretend this is a Client Component page in Next.js
  const product = { name: 'Blue Sneakers' };
  useEffect(() => {
    document.title = product.name; // only runs after JS hydrates
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h1>{product.name}</h1>
      <p>Setting title via document.title in useEffect — bad for SEO.</p>
    </div>
  );
}

